const VERIFY_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['accurate', 'stubMarkerRemains', 'issues', 'summary'],
  properties: {
    accurate: { type: 'boolean', description: 'true only if no blocker/major issues' },
    stubMarkerRemains: { type: 'boolean', description: 'true if the literal "> **Stub.**" banner is still present' },
    issues: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['severity', 'problem', 'fix'],
        properties: {
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          location: { type: 'string', description: 'heading/line/snippet where the problem is' },
          problem: { type: 'string' },
          fix: { type: 'string', description: 'concrete correction grounded in source' },
        },
      },
    },
    summary: { type: 'string' },
  },
}

function srcList(p) {
  return p.sources.map((s) => '  - ' + s).join('\n')
}

function writePrompt(p) {
  return [
    'You are writing one page of the public Paigasus Helikon mdBook.',
    '',
    'STEP 1: Read the shared ground-facts brief at ' + BRIEF + ' and follow every rule in it.',
    'STEP 2: Read these ground-truth source files to anchor yourself (read more of the surrounding crate if you need to confirm a name):',
    srcList(p),
    'STEP 3: Read the current page at ' + p.file + ' to preserve its H1 title and match the house voice.',
    '',
    'TASK: Write the COMPLETE replacement content for the page ' + p.file + ' and save it with the Write tool.',
    '',
    'Page-specific guidance: ' + p.guide,
    '',
    'HARD CONSTRAINTS: Ground every type / trait / method / builder call / feature / import path in the source you actually read — invent nothing. Do NOT run git. Do NOT run cargo. Write ONLY the single file ' + p.file + ' (do not touch SUMMARY.md, book.toml, or any other file).',
    '',
    'Return (as your final message, which is data not prose for a human): a 2-4 sentence summary of what you wrote, plus a bullet list of any API names you were UNSURE about so the verifier can double-check them.',
  ].join('\n')
}

function verifyPrompt(p) {
  return [
    'You are an ADVERSARIAL documentation reviewer. Your job is to catch inaccuracies in a freshly-written mdBook page before it ships.',
    '',
    'STEP 1: Read the shared brief at ' + BRIEF + '.',
    'STEP 2: Read the ground-truth source files:',
    srcList(p),
    'STEP 3: Read the freshly-written page at ' + p.file + '.',
    '',
    'Check, strictly against the source:',
    '(a) Does every type / trait / method / builder call / feature flag / import path mentioned ACTUALLY EXIST with the signature shown? Any hallucinated or wrong-signature API is a blocker.',
    '(b) Do all INTERNAL markdown links point only to pages in the brief source tree, with correct relative paths? Dead/invented links are a blocker (mdBook linkcheck fails the build).',
    '(c) Does the literal stub banner "> **Stub.**" still remain anywhere? If so set stubMarkerRemains=true.',
    '(d) Do code snippets match the canonical patterns / real examples (import paths, the RunContext::new 5-arg list, builder method names)?',
    '(e) Are stub crates (evals, runtime-axum/temporal/agentcore) honestly marked not-yet-implemented rather than documented as working?',
    '(f) Tone/scope per the brief.',
    '',
    'Be skeptical: when uncertain whether an API is real, FLAG it rather than pass. Set accurate=false if there is any blocker or major issue. Return the structured verdict.',
  ].join('\n')
}

function fixPrompt(p, verdict) {
  const lines = (verdict.issues || []).map((i) => '  - [' + i.severity + '] ' + (i.location ? i.location + ': ' : '') + i.problem + ' -> FIX: ' + i.fix)
  return [
    'A review found issues in the mdBook page ' + p.file + '. Fix them.',
    '',
    'STEP 1: Read the brief at ' + BRIEF + ' and these source files to re-ground yourself:',
    srcList(p),
    'STEP 2: Read the current page at ' + p.file + '.',
    'STEP 3: Edit the file to FIX exactly the issues below, re-grounding every change in the source (do not add claims not supported by source). If stubMarkerRemains is true, remove the "> **Stub.**" banner and ensure the page has real content.',
    '',
    'stubMarkerRemains: ' + verdict.stubMarkerRemains,
    'Issues:',
    lines.length ? lines.join('\n') : '  (none enumerated — re-verify and tighten accuracy)',
    '',
    'Do NOT run git or cargo. Edit ONLY ' + p.file + '. Return a short summary of the fixes you made.',
  ].join('\n')
}

phase('Write')
log('Refreshing ' + PAGES.length + ' mdBook pages (write -> verify -> fix), each grounded in source')

const results = await pipeline(
  PAGES,
  (p) => agent(writePrompt(p), { label: 'write:' + p.short, phase: 'Write' }).then((s) => ({ p, writeSummary: s })),
  (w, p) => agent(verifyPrompt(p), { label: 'verify:' + p.short, phase: 'Verify', schema: VERIFY_SCHEMA }),
  (verdict, p) => {
    if (!verdict) return { page: p.short, status: 'verify-failed', file: p.file }
    const needFix = verdict.stubMarkerRemains || (verdict.issues && verdict.issues.length > 0)
    if (!needFix) return { page: p.short, status: 'clean', file: p.file, verdict }
    return agent(fixPrompt(p, verdict), { label: 'fix:' + p.short, phase: 'Fix' })
      .then((summary) => ({ page: p.short, status: 'fixed', file: p.file, issueCount: verdict.issues.length, summary, verdict }))
  }
)

const clean = results.filter((r) => r && r.status === 'clean').length
const fixed = results.filter((r) => r && r.status === 'fixed').length
const failed = results.filter((r) => !r || r.status === 'verify-failed').length
log('Done: ' + clean + ' clean, ' + fixed + ' fixed, ' + failed + ' verify-failed')

return { clean, fixed, failed, results }

